// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
        bytes32 role = keccak256("MY_ROLE");
        bytes32 adminRole = keccak256("MY_ADMIN_ROLE");
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role) public {
        vm.assume(role != bytes32(0));
        bytes32 timelockAdminRole = keccak256("TIMELOCK_ADMIN_ROLE");
        bytes32 proposerRole = keccak256("PROPOSER_ROLE");
        bytes32 executorRole = keccak256("EXECUTOR_ROLE");
        vm.assume(role != timelockAdminRole);
        vm.assume(role != proposerRole);
        vm.assume(role != executorRole);

        bytes32 admin = c.getRoleAdmin(role);
        assertEq(admin, bytes32(0), "Reference: admin should be 0x00 for unset role");
    }
}
